const paper = $('Webhook - Paper Submission').first().json.body || $('Webhook - Paper Submission').first().json;
const methodology = String(paper.methodology || '');
const design = String(paper.study_design || '').toLowerCase();
const sampleSize = Number(paper.sample_size || 0);
let verdict = 'needs_detail';
if (methodology.length > 120 && sampleSize >= 30 && design) verdict = 'methodology_plausible';
if (sampleSize > 0 && sampleSize < 20) verdict = 'sample_too_small';
return [{
  json: {
    tool_name: 'methodology_quality_lookup',
    verdict,
    sample_size: sampleSize,
    study_design: paper.study_design || 'not provided',
    evidence: 'Checks methodology length, study design presence, and sample-size reasonableness.'
  }
}];

const paper = $('Webhook - Paper Submission').first().json.body || $('Webhook - Paper Submission').first().json;
const gap = String(paper.research_gap || '').toLowerCase();
const keywords = Array.isArray(paper.keywords) ? paper.keywords : String(paper.keywords || '').split(',').map(k => k.trim()).filter(Boolean);
const crowded = ['chatbot', 'sentiment analysis', 'fake news', 'recommendation system'];
const overlap = keywords.filter(k => crowded.includes(String(k).toLowerCase()));
return [{
  json: {
    tool_name: 'contribution_gap_lookup',
    crowded_topic_matches: overlap,
    gap_strength: gap.length > 100 ? 'clear_gap_claim' : 'weak_gap_claim',
    evidence: overlap.length ? 'Topic overlaps with common paper/project areas; contribution must be sharply differentiated.' : 'No obvious crowded-topic keyword match in the hardcoded database.'
  }
}];

